function IdolLive3D_FullScreenFX:__init( opTF_, edTF_, color_, isUseDefaultParams_ )
    if isNull(opTF_) or isNull(edTF_) then 
        return
    end 
    ---
    self.mainCamera = IdolLive3D_Utils.GetMainCamera()
    self.opTF = opTF_
    self.edTF = edTF_
    self.color = Color( color_.r, color_.g, color_.b, color_.a )
    --- 

    -- op:
    self.opStartTime = 0.5
    local posOff = Vector3.zero
    if isNotNull(self.opTF) then 
        if isUseDefaultParams_ ~= true then
            local opParams = KTool.GetComponent(self.opTF.gameObject, typeof(LuaParameters))
            if isNotNull(opParams) then 
                self.opStartTime = LuaParametersReader.Read( opParams, "startTime", LuaParametersType.Float )
                posOff = LuaParametersReader.Read( opParams, "localPos", LuaParametersType.Vector3 )
            else
                printError( "全屏特效 op 忘记挂载脚本 LuaParameters; 将使用默认参数" )
            end 
        end
        ---
        self.opTF:SetParent( self.mainCamera.transform, false )
        self.opTF.localPosition = posOff
        self.opTF.localRotation = Quaternion.identity
        self.opTF.localScale = Vector3.one
        ---
        CfUtils.SetActive( self.opTF, false )
    end
    self.lastUsedOpStartTime = self.opStartTime

    -- ed:
    self.edEndTime = 0.5
    if isNotNull(self.edTF) then 
        if isUseDefaultParams_ ~= true then
            local edParams = KTool.GetComponent(self.edTF.gameObject, typeof(LuaParameters))
            if isNotNull(edParams) then 
                self.edEndTime = LuaParametersReader.Read( edParams, "endTime", LuaParametersType.Float )
            else
                printError( "全屏特效 ed 忘记挂载脚本 LuaParameters, 将使用默认参数" )
            end 
        end
        --- 
        self.edTF:SetParent( self.mainCamera.transform, false )
        self.edTF.localPosition = posOff
        self.edTF.localRotation = Quaternion.identity
        self.edTF.localScale = Vector3.one
        ---
        CfUtils.SetActive( self.edTF, false )
    end

    --- 
    self.state = IdolLive3D_States.FullScreenFXState.Hide

    ---
    self.isInit = true
end


