-- 协程
---@param opStartTime_ number | nil
function IdolLive3D_FullScreenFX:FadeIn( opStartTime_ )
    if self.isInit ~= true then 
        return
    end 
    if self.state ~= IdolLive3D_States.FullScreenFXState.Hide then 
        print( "state = " .. tostring(self.state) )
        return
    end 
    self.state = IdolLive3D_States.FullScreenFXState.FadeIn
    CfUtils.SetActive( self.opTF, true )
    ---
    if type(opStartTime_) ~= "number" then 
        opStartTime_ = self.opStartTime
    end 
    opStartTime_ = Mathf.Max( opStartTime_, 0.0 )
    self.lastUsedOpStartTime = opStartTime_
    ---
    Events.Broadcast( IdolLive3D_States.EventShowUIFullPanel, true, opStartTime_, self.color )
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( opStartTime_ ))
    ---
    self.state = IdolLive3D_States.FullScreenFXState.Show
end


-- 协程
---@param edEndTime_ number | nil
function IdolLive3D_FullScreenFX:FadeOut( edEndTime_ )
    --printError("FadeOut")
    if self.isInit ~= true then 
        return
    end 

    if self.state == IdolLive3D_States.FullScreenFXState.FadeOut then 
        printError( "已经在 FadeOut 流程中, 先啥也不干" )
        return
    end 

    -- 避免此时 FadeIn 流程没有走完
    if self.state == IdolLive3D_States.FullScreenFXState.FadeIn then 
        local startTime = Time.time
        while (Time.time-startTime) < checkNumber(self.lastUsedOpStartTime) do 
            if self.state == IdolLive3D_States.FullScreenFXState.Show then
                break
            end
            coroutine.yield(Yielders.EndOfFrame)
        end 
    end 

    -- 异常:
    if self.state ~= IdolLive3D_States.FullScreenFXState.Show then 
        printError( "FadeOut 过程异常, 强制退出来" )
        CfUtils.SetActive( self.opTF, false ) -- !! 防止出不来
        CfUtils.SetActive( self.edTF, false ) -- !! 防止出不来
        self.state = IdolLive3D_States.FullScreenFXState.Hide
        return
    end 
    ---
    self.state = IdolLive3D_States.FullScreenFXState.FadeOut
    CfUtils.SetActive( self.edTF, true )
    coroutine.yield(Yielders.EndOfFrame)   
    CfUtils.SetActive( self.opTF, false )
    ---
    if type(edEndTime_) ~= "number" then 
        edEndTime_ = self.edEndTime
    end 
    edEndTime_ = Mathf.Max( edEndTime_, 0.0 )
    ---
    Events.Broadcast( IdolLive3D_States.EventShowUIFullPanel, false, edEndTime_, nil )
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds( edEndTime_ ))
    ---
    self.state = IdolLive3D_States.FullScreenFXState.Hide
    CfUtils.SetActive( self.edTF, false )
end


-- 协程
function IdolLive3D_FullScreenFX:WaitTargetState( tgtState_ )
    local isWaited = false
    for i=0, 500 do 
        if self.state == tgtState_ then 
            isWaited = true
            break
        end 
        coroutine.yield(Yielders.EndOfFrame)
    end
    if isWaited ~= true then 
        printError("始终没等到; 参数 tgtState_ = " .. tostring(tgtState_))
    end 
end




